def content(lang):
    t = TEXT[lang]; c = COLS[lang]
    head = "".join(f'<th scope="col">{x}</th>' for x in c)
    body = "".join("<tr>" + f'<th scope="row">{r[0]}</th>' + "".join(f"<td>{x}</td>" for x in r[1:]) + "</tr>" for r in ROWS[lang])
    ch = "".join(f"<li>{x}</li>" for x in t["changes"])
    src = "".join(f'<li><a href="{u}" target="_blank" rel="noopener">{n}</a></li>' for n, u in SRC)
    inner = f"""<p>{t['intro']}</p>
<div class="invite"><p><b>{t['note_h']}.</b> {t['note']}</p></div>
<div class="tablewrap" role="region" aria-label="{t['table_cap']}" tabindex="0"><table class="cmp"><caption>{t['table_cap']}</caption><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>
<p class="updated">{t['scroll']}</p>
<h2>{t['changes_h']}</h2><ul>{ch}</ul>
<h2>{t['next_h']}</h2><p>{t['next']}</p>
<h2>{t['src_h']}</h2><ol class="srcs">{src}</ol>
<p class="updated">{t['checked']}</p>"""
    return t["title"], t["desc"], inner
